2641	// jsScanPartialFailure maps a relation-phase JS/TS scope-parse error to the
2642	// partial-failure record the summary reports, mirroring the entity-phase
2643	// codes (E_PARSE_TIMEOUT for a blown parse budget, E_PARSE_ERROR otherwise).
2644	func jsScanPartialFailure(path string, err error) PartialFailure {
2645		code := "E_PARSE_ERROR"
2646		if errors.Is(err, context.DeadlineExceeded) {
2647			code = "E_PARSE_TIMEOUT"
2648		}
2649		return PartialFailure{
2650			Code:                 code,
2651			Severity:             "warning",
2652			FilePath:             path,
2653			EffectOnCompleteness: "relation-phase scope parse failed; namespace-qualified call classification skipped for this file",
2654			Detail:               err.Error(),
2655		}
2656	}
2657	
2658	func forEachRelation(repoKey string, files []FileRecord, recordsByFile map[string][]SymbolRecord, readContent contentReader, precomputedImports map[string][]string, spec profileSpec, shouldStop func() bool, emit func(RelationRecord), recordFailure func(PartialFailure)) {
2659		if spec.name == ProfileSyntaxOnly {
2660			emitStructuralRelations(repoKey, files, recordsByFile, emit)
2661			return
2662		}
2663		needsTool := spec.emits("HANDLES_TOOL")
2664		needsCallScan := spec.emits("CALLS") && spec.callResolution != "none"
2665		needsReceiverCalls := spec.emits("CALLS") && spec.callResolution == "full"
2666		needsFields := spec.emits("READS_FIELD") || spec.emits("WRITES_FIELD") || spec.emits("ACCESSES")
2667		needsTypes := spec.emits("EXTENDS") || spec.emits("INHERITS") || spec.emits("IMPLEMENTS") || spec.emits("OVERRIDES")
2668		needsOverrides := spec.emits("OVERRIDES")
2669		// C# extension methods and Kotlin extension functions/properties are members
2670		// of the type they extend for every purpose except where they are written.
2671		// The extra CONTAINS edge is what makes them answer "what can I do with an
2672		// Edit?". It resolves same-file first, so it still works at profiles that
2673		// build no cross-file type index.
2674		needsExtensionMembers := spec.emits("CONTAINS")
2675		needsAsyncCalls := spec.emits("ASYNC_CALLS")
2676		needsDataFlow := spec.emits("DATA_FLOWS")
2677		needsServiceRelations := spec.emits("HANDLES_GRPC") || spec.emits("HANDLES_GRAPHQL") || spec.emits("HANDLES_TRPC")
2678		// Shallow call resolution needs the global short-name index too: without
2679		// it, cross-file targets are invisible and shallow degenerates to
2680		// same-file calls only, leaving the fast profile with no caller edges for
2681		// graph-aware ranking. The emit-time shallowCallRelationRetained filter
2682		// still drops the low-precision resolutions the index makes reachable.
2683		needsSignatureTypeImports := spec.emits("USES_TYPE") || spec.emits("PARAM_TYPE") || spec.emits("RETURNS_TYPE") || spec.emits("TESTS")
2684		needsGlobalSymbolsByShortName := spec.callResolution == "full" || spec.callResolution == "shallow" ||
2685			needsReceiverCalls || needsFields || needsTypes || needsOverrides || needsAsyncCalls ||
2686			needsDataFlow || needsSignatureTypeImports
2687		needsGlobalSymbolsByFile := needsGlobalSymbolsByShortName
2688		symbolsByShortName := map[string][]SymbolRecord{}
2689		symbolsByFile := map[string][]SymbolRecord{}
2690		childNamesByContainer := map[string]map[string]bool{}
2691		methodsByContainer := map[string]map[string]SymbolRecord{}
2692		fieldsByContainer := map[string]map[string]SymbolRecord{}
2693		returnTypesBySymbolNameAndFile := map[string]map[string][]string{}
2694		returnTypesBySymbolNameAndDir := map[string]map[string][]string{}
2695		var inheritanceEdges []RelationRecord // captured for OVERRIDES derivation
2696		routeHandlers := map[string][]SymbolRecord{}
2697		httpCallsByRoute := map[string][]RelationRecord{}
2698		graphqlSchemaFields := map[string][]SymbolRecord{}
2699		graphqlResolvers := map[string][]SymbolRecord{}
2700		graphqlOperationRootAliases := map[string]string{}
2701		for _, file := range files {
2702			for _, symbol := range recordsByFile[file.Path] {
2703				if symbol.Kind != "graphql_schema_field" {
2704					continue
2705				}
2706				rootName := graphqlRootNameFromSignature(symbol)
2707				if rootName == "" || !graphqlOperationRoot(rootName) {
2708					continue
2709				}
2710				if typeName, _, ok := strings.Cut(symbol.QualifiedName, "."); ok {
2711					graphqlOperationRootAliases[strings.ToLower(typeName)] = rootName
2712				}
2713			}
2714		}
2715		// Cross-file container index: entitySymbols links a member to its container
2716		// only within one file, but some containers span files — a Go receiver type
2717		// commonly lives in a different file of the same package than its methods
2718		// (C# partial classes and reopened Ruby classes behave the same) — leaving
2719		// such members with an empty ContainerID and therefore invisible to
2720		// receiver-typed call resolution. Resolve those containers from the
2721		// member's qualified-name prefix against the workspace's type-like symbols.
2722		crossFileContainers := needsCallScan || needsReceiverCalls || needsFields || needsOverrides
2723		// Cross-file namespace membership is only consulted by the JS/TS
2724		// merged-declaration fallback (rare), and the lookup memoizes per file, so
2725		// building the closure up front costs nothing for repositories without
2726		// TypeScript namespaces.
2727		foreignJSNamespaceOf := jsCrossFileNamespaceLookup(readContent, recordsByFile)
2728		typeLikeByShortName := map[string][]SymbolRecord{}
2729		if crossFileContainers {
2730			for _, file := range files {
2731				for _, symbol := range recordsByFile[file.Path] {
2732					if typeLikeKind(symbol.Kind) {
2733						typeLikeByShortName[symbol.Name] = append(typeLikeByShortName[symbol.Name], symbol)
2734					}
2735				}
2736			}
2737		}
2738		partialContainerCanonical, partialContainerFile := partialTypeCanonicalIDs(files, recordsByFile)
2739		// Iterate files in their (stable) slice order, not the recordsByFile map, so
2740		// structural relations stream deterministically.
2741		for _, file := range files {
2742			if shouldStop != nil && shouldStop() {
2743				return
2744			}
2745			records := recordsByFile[file.Path]

