1331	func topLevelBlockFromLines(lines []string, symbols []SymbolRecord) string {
1332		if len(lines) == 0 {
1333			return ""
1334		}
1335		masked := append([]string(nil), lines...)
1336		for _, symbol := range symbols {
1337			start := maxInt(1, symbol.StartLine)
1338			end := maxInt(start, symbol.EndLine)
1339			if start > len(masked) {
1340				continue
1341			}
1342			if end > len(masked) {
1343				end = len(masked)
1344			}
1345			for i := start - 1; i <= end-1; i++ {
1346				masked[i] = ""
1347			}
1348		}
1349		return strings.Join(masked, "\n")
1350	}
