188	
189	func alpha(a int) int {
190		return bravo(a)
191	}
192	
193	func bravo(b int) int {
194		value := alpha(b)
195		return value
196	}
197	`,
198				wantCode: true,
199				// Both orientations of the pair have two producers.
200				wantEdge: "2 DATA_FLOWS edge(s)",
201			},
202			{
203				name: "one-directional flow loses nothing",
204				source: `package flow
205	
206	func sink(a int) int { return a }
207	
208	func caller(a int) int {
209		return sink(a)
210	}
211	`,
212				wantCode: false,
213			},
214		} {
215			t.Run(testCase.name, func(t *testing.T) {
216				repo := t.TempDir()
217				writeFile(t, repo, "flow.go", testCase.source)
218	
219				var summary SnapshotSummary
220				err := StreamSnapshot(t.Context(), repo, "unmerged-test", ProviderSnapshotOptions{Worktree: true, Profile: ProfileFull}, func(record any) error {
221					if typed, ok := record.(SnapshotSummary); ok {
222						summary = typed
223					}
224					return nil
225				})
226				if err != nil {
227					t.Fatal(err)
228				}
229	
230				var found *ProviderWarning
231				for i, warning := range summary.Warnings {
232					if warning.Code == "W_DATA_FLOW_EVIDENCE_UNMERGED" {
233						found = &summary.Warnings[i]
234					}
235				}
236				if !testCase.wantCode {
237					if found != nil {
238						t.Fatalf("unexpected %s on a corpus with no multi-producer edge: %s", found.Code, found.Detail)
239					}
240					return
241				}
242				if found == nil {
243					t.Fatalf("no W_DATA_FLOW_EVIDENCE_UNMERGED warning; got %d warning(s)", len(summary.Warnings))
244				}
245				if found.Severity != "info" {
246					t.Fatalf("severity = %q, want %q: the graph is one-sided here, not wrong", found.Severity, "info")
247				}
