258	// TestDataFlowEvidenceBoundsAreIndependent pins the interaction between the two
259	// ways a DATA_FLOWS evidence array can be incomplete. They are orthogonal: the
260	// cap bounds what one producer contributes, and cross-symbol grouping bounds how
261	// many producers contribute at all. One edge can hit both, and when it does
262	// neither disclosure may swallow the other -- a reader who saw only
263	// EVIDENCE_TRUNCATED would conclude the missing flows are the ones past the cap,
264	// when a whole second producer is also absent.
265	//
266	// alpha forwards ten parameters into bravo, which truncates that direction at
267	// the cap, and bravo assigns alpha's return, which makes the same edge
268	// two-producer.
269	func TestDataFlowEvidenceBoundsAreIndependent(t *testing.T) {
270		repo := t.TempDir()
271		writeFile(t, repo, "flow.go", `package flow
272	
273	func alpha(a, b, c, d, e, f, g, h, i, j int) int {
274		return bravo(a, b, c, d, e, f, g, h, i, j)
275	}
276	
277	func bravo(a, b, c, d, e, f, g, h, i, j int) int {
278		value := alpha(a, b, c, d, e, f, g, h, i, j)
279		return value
280	}
281	`)
282	
283		var truncated *RelationRecord
284		var summary SnapshotSummary
285		err := StreamSnapshot(t.Context(), repo, "bounds-test", ProviderSnapshotOptions{Worktree: true, Profile: ProfileFull}, func(record any) error {
286			switch typed := record.(type) {
287			case RelationRecord:
288				if typed.Type == "DATA_FLOWS" && lastSegment(typed.FromID) == "alpha" && lastSegment(typed.ToID) == "bravo" {
289					kept := typed
290					truncated = &kept
291				}
292			case SnapshotSummary:
293				summary = typed
294			}
295			return nil
296		})
297		if err != nil {
298			t.Fatal(err)
299		}
300	
301		if truncated == nil {
302			t.Fatal("no alpha -> bravo DATA_FLOWS relation")
303		}
304		if len(truncated.Evidence) != dataFlowEvidenceLimit {
305			t.Fatalf("evidence entries = %d, want the cap %d", len(truncated.Evidence), dataFlowEvidenceLimit)
306		}
307		if !slices.Contains(truncated.WarningCodes, evidenceTruncatedWarning) {
308			t.Fatalf("warning codes = %q, want %q", truncated.WarningCodes, evidenceTruncatedWarning)
309		}
310	
311		var unmerged *ProviderWarning
312		for i, warning := range summary.Warnings {
313			if warning.Code == "W_DATA_FLOW_EVIDENCE_UNMERGED" {
314				unmerged = &summary.Warnings[i]
315			}
316		}
317		if unmerged == nil {
318			t.Fatal("a truncated edge that also has a second producer must still be counted; the cap does not supersede the cross-symbol bound")
319		}
320		if !strings.Contains(unmerged.Detail, "2 DATA_FLOWS edge(s)") {
321			t.Fatalf("detail = %q, want both orientations of the pair counted", unmerged.Detail)
322		}
323	}
