6746	// appendGoInterfaceImplementationCalls carries every CALLS edge that landed on a
6747	// Go interface method requirement through to the concrete methods that satisfy
6748	// it. It runs once over the finished relation list rather than at each of the
6749	// dozen typed-receiver tiers, so a call reached through a parameter type, a
6750	// returned type or a constructor chain is treated identically. Existing edges are
6751	// never rewritten — this is purely additive, and the interface node keeps the
6752	// incoming edge that used to be impossible (a Go interface had no method symbols
6753	// at all, so terraform's communicator.Communicator was a dead end).
6754	func appendGoInterfaceImplementationCalls(relations []RelationRecord, from SymbolRecord, symbolsByShortName map[string][]SymbolRecord, methodsByContainer map[string]map[string]SymbolRecord) []RelationRecord {
6755		if from.Language != "Go" || len(relations) == 0 {
6756			return relations
6757		}
6758		existing := map[string]bool{}
6759		for _, relation := range relations {
6760			if relation.Type == "CALLS" {
6761				existing[relation.ToID] = true
6762			}
6763		}
6764		// Deterministic order: walk the relations, not a map.
6765		var added []RelationRecord
6766		for _, relation := range relations {
6767			if relation.Type != "CALLS" {
6768				continue
6769			}
6770			// The target symbol is found through the short-name index the caller
6771			// already built (a full by-ID index would cost a workspace scan per
6772			// function body); a method ID always ends `:method:Container.Name`.
6773			ifaceMethod, ok := goMethodSymbolByID(relation.ToID, symbolsByShortName)
6774			if !ok {
6775				continue
6776			}
6777			for _, impl := range goInterfaceImplementationMethods(ifaceMethod, symbolsByShortName, methodsByContainer) {
6778				if impl.ID == from.ID || existing[impl.ID] {
6779					continue
6780				}
6781				existing[impl.ID] = true
6782				scope := "file"
6783				if impl.FilePath != from.FilePath {
6784					scope = "module"
6785				}
