6801						Kind:      "call_site",
6802						FilePath:  from.FilePath,
6803						StartLine: from.StartLine,
6804						EndLine:   from.EndLine,
6805						Detail:    detail,
6806					}},
6807					WarningCodes: []string{},
6808				})
6809			}
6810		}
6811		return append(relations, added...)
6812	}
