 45	
 46	type neighborEndpoint struct {
 47		ID            string `json:"id"`
 48		Name          string `json:"name"`
 49		QualifiedName string `json:"qualified_name,omitempty"`
 50		Kind          string `json:"kind,omitempty"`
 51		FilePath      string `json:"file_path,omitempty"`
 52		StartLine     int    `json:"start_line,omitempty"`
 53		// EndLine closes the definition span. Reported so one answer can state both
 54		// the definition line and the span it covers, instead of leaving a reader to
 55		// reconcile a bare line number here against a line range from `search`.
 56		EndLine  int    `json:"end_line,omitempty"`
 57		Language string `json:"language,omitempty"`
 58		External bool   `json:"external,omitempty"`
 59	}
 60	
 61	type neighborEdge struct {
 62		Direction  string           `json:"direction"`
 63		Relation   string           `json:"relation"`
 64		Endpoint   neighborEndpoint `json:"endpoint"`
 65		Confidence float64          `json:"confidence"`
 66		Resolution string           `json:"resolution,omitempty"`
 67		Reason     string           `json:"reason,omitempty"`
 68		Evidence   []sem.Evidence   `json:"evidence,omitempty"`
 69		// CallSite is where the call is actually written, resolved from the caller's
 70		// body. Nil when it could not be resolved, in which case the endpoint's
 71		// definition line is all this answer knows.
 72		CallSite *callSite `json:"call_site,omitempty"`
 73	}
 74	
 75	type neighborPath struct {
 76		Caller neighborEndpoint `json:"caller"`
 77		Focus  neighborEndpoint `json:"focus"`
 78		Callee neighborEndpoint `json:"callee"`
 79	}
 80	
 81	type neighborFocus struct {
 82		Symbol   neighborEndpoint `json:"symbol"`
610	func neighborRelationMatches(requested, actual string) bool {
611		// Constructors are callable dependencies. The provider schema keeps
612		// CONSTRUCTS distinct, while the focused call-neighborhood view includes
613		// them so "callees" does not silently omit direct constructor invocations.
614		return actual == requested || (requested == "CALLS" && actual == "CONSTRUCTS")
615	}
