func LoadCompactSnapshot(in io.Reader) (*CompactSnapshotIndex, error) {
	index := &CompactSnapshotIndex{symbolMatches: map[string][]int{}, relationsByFrom: map[string][]int{}}
	hasher := NewSnapshotSemanticHasher()
