  tools.exec_command({
    cmd: "gh search code '\"compact-ndjson\" org:entireio' --limit 100 --json repository,path,url,textMatches",
    workdir: "/Users/thomi/.codex/worktrees/7c7e/entire-graph",
    yield_time_ms: 30000,
    max_output_tokens: 20000
  }),
  tools.exec_command({
    cmd: "gh search code '\"snapshot-query\" org:entireio' --limit 100 --json repository,path,url,textMatches",
    workdir: "/Users/thomi/.codex/worktrees/7c7e/entire-graph",
    yield_time_ms: 30000,
    max_output_tokens: 16000
  }),
  tools.exec_command({
    cmd: "gh search code '\"DecodeCompactSnapshot\" org:entireio' --limit 100 --json repository,path,url,textMatches",
    workdir: "/Users/thomi/.codex/worktrees/7c7e/entire-graph",
    yield_time_ms: 30000,
    max_output_tokens: 12000
  })
]);
text("COMPACT\n" + results[0].output);
text("SNAPSHOT QUERY\n" + results[1].output);
text("DECODER\n" + results[2].output);

