+	if err := Run(t.Context(), Options{Version: "0.1.0", Env: EntireEnv{RepoRoot: repo}, Stdout: &out}, []string{
+		"neighbors", "--repo", repo, "--symbol", "caller", "--direction", "out",
+		"--relation", "DATA_FLOWS", "--format", "json",
+	}); err != nil {
+		t.Fatal(err)
+	}
