    ]


def test_first_parent_git_reader_rejects_unparseable_output(tmp_path) -> None:
    from graphify_parity.temporal import parse_git_log

    try:
        parse_git_log("not-a-sha without-a-tab")
    except ValueError as error:
        assert str(error) == "invalid first-parent git log line"
    relations: list[str] = []
    header: dict[str, Any] = {}
    summary: dict[str, Any] = {}
    snapshot_format: str | None = None
    compact_dictionary = [""]
    compact_seen_summary = False
    for line_number, line in enumerate(
        path.read_text(encoding="utf-8").splitlines(), start=1
    ):
        if not line:
            continue
        try:
            record = json.loads(line)
        except json.JSONDecodeError as error:
            raise ValueError(f"invalid Entire snapshot line {line_number}") from error
        if snapshot_format is None:
            snapshot_format = "compact" if isinstance(record, list) else "ndjson"
        if snapshot_format == "compact":
            if not isinstance(record, list) or not record or not isinstance(record[0], str):
                raise ValueError(f"invalid compact Entire snapshot line {line_number}")
            if compact_seen_summary:
                raise ValueError("compact Entire snapshot has a record after its summary")
            tag = record[0]
            if tag == "h":
                if line_number != 1 or len(record) != 3 or record[1] != 1:
                    raise ValueError("invalid compact Entire snapshot header")
                if not isinstance(record[2], dict):
                    raise ValueError("invalid compact Entire snapshot header payload")
                header = record[2]
            elif tag == "d":
                if (
                    not header
                    or len(record) != 3
                    or type(record[1]) is not int
                    or record[1] != len(compact_dictionary)
                    or not isinstance(record[2], list)
                    or not record[2]
                    or not all(isinstance(value, str) and value for value in record[2])
                ):
                    raise ValueError("invalid compact Entire snapshot dictionary update")
                compact_dictionary.extend(record[2])
            elif tag in {"f", "x", "s", "r"}:
                expected_arities = {
                    "f": (6,),
                    "x": (12,),
                    "s": (14,),
                    "r": (11, 12),  # v1 may append evidence_dropped.
                }[tag]
                if not header or len(record) not in expected_arities:
                    raise ValueError(f"invalid compact Entire snapshot {tag} record")
                if tag == "r" and len(record) == 12:
                    evidence_dropped = record[11]
                    if type(evidence_dropped) is not int or evidence_dropped < 0:
                        raise ValueError(
                            "invalid compact Entire snapshot evidence_dropped "
                            f"on line {line_number}"
                        )
                if tag == "f":
                    files += 1
                elif tag in {"s", "r"}:
                    dictionary_index = record[3]
                    if (
                        type(dictionary_index) is not int
                        or dictionary_index < 0
                        or dictionary_index >= len(compact_dictionary)
                    ):
                        raise ValueError(
                            f"invalid compact Entire snapshot dictionary index on line {line_number}"
                        )
                    if tag == "s":
                        node_kinds.append(compact_dictionary[dictionary_index])

